  dat=np.load(f);t=time.time()
  out=mp_signs(int(dat['m']),float(dat['R']),float(dat['d']),dat['lo'],dat['up'],prec=150)
  print(f,out,'time',time.time()-t,flush=True)
 raise SystemExit
